PR_TA=[('வைகை ஃப்ரெஷ் பால்','தினசரி பாஸ்டரைஸ் பால், சுத்தமான மூடிய பாக்கெட்டில்.'),('பாதாம் பால்','வறுத்த பாதாமும் குங்குமப்பூவும் சேர்ந்த குளிர்ந்த, கெட்டியான பால்.'),('பண்ணை நெய்','தங்க நிறம், மணம். புதிய கிரீமில் மெதுவாகத் தயாரிக்கப்பட்டது.'),('கெட்டித் தயிர்','பாரம்பரிய மண்பானையில் உறைய வைக்கப்பட்டது. கெட்டியாக, குளிர்ச்சியாக.'),('புதிய வெண்ணெய்','குளிர்ந்த, மிருதுவான, அளவான உப்புடன்.'),('கண்ணாடி பாட்டில் பால்','திருப்பித் தரக்கூடிய கண்ணாடியில் முழு கிரீம் பால். தூய்மை, எளிமை.')]
MO_TA=['முதல் ஃபில்டர் காபிக்கு வாசலிலேயே புதிய பாட்டில்கள்.','குளிர்ந்த பாதாம் பால் வாழைப்பழம், பேரீச்சையுடன் மென்மையாகக் கலக்கும்.','இட்லி, தோசை அல்லது சிறுதானியக் கஞ்சியுடன் கெட்டித் தயிர்.','பள்ளி உணவுப் பெட்டிக்கும் இரவு நேரப் பாலுக்கும் எளிய மூடிய பாக்கெட்டுகள்.','பாயசம், அல்வா, பண்டிகை இனிப்புகளுக்கு வெண்ணெயும் நெய்யும்.','பால், பன்னீர், நெய், தயிர். முழு குடும்பத்துக்கும் ஒரே ஆர்டரில்.']
FAQ_TA=[('மதுரையில் எந்தப் பகுதிகளுக்கு விநியோகம் செய்கிறீர்கள்?','அண்ணா நகர், கே.கே. நகர், தெப்பக்குளம், கோரிப்பாளையம், திருநகர், தல்லாகுளம் மற்றும் அருகிலுள்ள பகுதிகளுக்கு. உங்கள் தெருவை உறுதிசெய்ய பின்கோடுடன் வாட்ஸ்அப்பில் தெரிவியுங்கள்.'),
('விநியோகம் எத்தனை மணிக்கு?','காலை 5:30க்குள் உங்கள் வாசலுக்கு பால் வந்து சேரும், நாளின் முதல் காபிக்குத் தயாராக.'),
('வைகை பால் பாஸ்டரைஸ் செய்யப்பட்டு சோதிக்கப்படுகிறதா?','ஆம். ஒவ்வொரு தொகுப்பும் பண்ணையிலும், குளிர்விப்பு நிலையத்திலும், மீண்டும் எங்கள் பால் நிலையத்திலும் சோதிக்கப்பட்டு, மூடப்பட்டு, விநியோகிக்கப்படுகிறது.'),
('கண்ணாடி பாட்டிலில் பால் கிடைக்குமா?','ஆம். முழு கிரீம் பால் திருப்பித் தரக்கூடிய கண்ணாடி பாட்டில்களிலும், மூடிய கார்ட்டன் மற்றும் பாக்கெட்டுகளிலும் கிடைக்கிறது.'),
('ஆர்டர் செய்வது அல்லது தினசரி திட்டத்தைத் தொடங்குவது எப்படி?','இந்தப் பக்கத்தில் கூடையில் பொருட்களைச் சேர்த்து வாட்ஸ்அப்பில் அனுப்புங்கள், அல்லது தினசரி/வாராந்திர விநியோகத்துக்கு நேரடியாகத் தொடர்பு கொள்ளுங்கள்.'),
('கஃபே, உணவகம், மொத்த வாங்குபவர்களுக்கு விநியோகம் உண்டா?','உண்டு. மதுரையில் கஃபேக்கள், ஹோட்டல்கள், கேட்டரிங் நிறுவனங்களுக்கு பால், தயிர், பன்னீர், வெண்ணெய், நெய் மொத்தமாக வழங்குகிறோம். விலைக்குத் தொடர்பு கொள்ளுங்கள்.')]

